-- 현재 지도에서 사용하는 event_landmarks: 기존 자료 유지, 중복 제외 후 추가
-- 원본: cityname_split/03_행사.sql. 좌표와 시군구가 확인되는 자료만 포함.
-- 행사 기간은 원본 기준으로 설명에 표시합니다. 과거 행사도 포함됩니다.
SET NAMES utf8mb4;
USE `cityname`;

CREATE TABLE IF NOT EXISTS `event_landmarks` (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  region_code CHAR(2) NOT NULL,
  locality_name VARCHAR(50) NOT NULL,
  title VARCHAR(120) NOT NULL,
  description VARCHAR(255) NOT NULL,
  latitude DECIMAL(10,6) NULL,
  longitude DECIMAL(10,6) NULL,
  location_url VARCHAR(500) NOT NULL,
  source_name VARCHAR(100) NOT NULL,
  INDEX idx_lookup(region_code, locality_name),
  CONSTRAINT fk_event_landmarks_region FOREIGN KEY (region_code) REFERENCES regions(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 민간 행사처럼 좌표가 제공되지 않은 기록도 NULL로 보존합니다.
ALTER TABLE `event_landmarks`
 MODIFY `latitude` DECIMAL(10,6) NULL,
 MODIFY `longitude` DECIMAL(10,6) NULL;

CREATE TEMPORARY TABLE `cityname_event_import` LIKE `event_landmarks`;
START TRANSACTION;



















































SELECT p.region_code,p.locality_name,p.title,p.description,p.latitude,p.longitude,p.location_url,p.source_name
FROM `cityname_event_import` p
JOIN `regions` r ON r.code=p.region_code
WHERE NOT EXISTS (
 SELECT 1 FROM `event_landmarks` t
 WHERE t.region_code=p.region_code AND t.locality_name=p.locality_name
 AND REPLACE(t.title,' ','')=REPLACE(p.title,' ','')
 AND SUBSTRING_INDEX(t.description,' | ',1)=SUBSTRING_INDEX(p.description,' | ',1)
 AND ((t.latitude BETWEEN p.latitude-0.00025 AND p.latitude+0.00025
 AND t.longitude BETWEEN p.longitude-0.00025 AND p.longitude+0.00025))
);
SELECT ROW_COUNT() AS added_rows;
COMMIT;
DROP TEMPORARY TABLE `cityname_event_import`;

-- BEGIN PRIVATE EVENTS
-- 사용자 제공 민간행사 82건. 지역 미상 자료도 원본 테이블에 보존합니다.
-- 좌표는 공급되지 않았으므로 NULL 유지. 지역이 확인되는 자료만 지도 행사에 연결합니다.
CREATE TABLE IF NOT EXISTS `private_event_research` (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,
 source VARCHAR(30) NOT NULL,
 event_name VARCHAR(300) NOT NULL,
 category VARCHAR(80),
 start_date DATE NULL,
 end_date DATE NULL,
 area VARCHAR(120),
 venue_or_address VARCHAR(300),
 latitude DECIMAL(10,7) NULL,
 longitude DECIMAL(10,7) NULL,
 source_url TEXT NOT NULL
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE `cityname_private_event_import` LIKE `private_event_research`;
CREATE TEMPORARY TABLE `cityname_private_map_import` LIKE `event_landmarks`;
START TRANSACTION;

SELECT p.source,p.event_name,p.category,p.start_date,p.end_date,p.area,p.venue_or_address,p.latitude,p.longitude,p.source_url
FROM `cityname_private_event_import` p
WHERE NOT EXISTS (SELECT 1 FROM `private_event_research` s WHERE
s.source <=> p.source AND s.event_name <=> p.event_name AND s.category <=> p.category AND s.start_date <=> p.start_date AND s.end_date <=> p.end_date AND s.area <=> p.area AND s.venue_or_address <=> p.venue_or_address AND s.source_url <=> p.source_url);
SELECT ROW_COUNT() AS added_private_source_rows;


SELECT p.region_code,p.locality_name,p.title,p.description,p.latitude,p.longitude,p.location_url,p.source_name
FROM `cityname_private_map_import` p JOIN `regions` r ON r.code=p.region_code
WHERE NOT EXISTS (SELECT 1 FROM `event_landmarks` e
 WHERE e.region_code=p.region_code AND e.locality_name=p.locality_name
 AND REPLACE(e.title,' ','')=REPLACE(p.title,' ','')
 AND SUBSTRING_INDEX(e.description,' | ',1)=SUBSTRING_INDEX(p.description,' | ',1));
SELECT ROW_COUNT() AS added_private_map_rows;
COMMIT;
DROP TEMPORARY TABLE `cityname_private_event_import`;
DROP TEMPORARY TABLE `cityname_private_map_import`;
